`, "",{"version":3,"sources":["webpack://./src/ARK_STATUSBAR/views/global_tabs/worldbook/WorldbookTab.vue"],"names":[],"mappings":"AA4UA,mBACE,YACF,CACA,mBACE,kBACF","sourcesContent":["<template>\n  <div class=\"relative w-full h-full slim-scroll-container overflow-y-auto flex flex-col box-border\">\n    <!-- Inner content wrapper with padding -->\n    <div class=\"p-2 flex flex-col gap-2 min-h-max box-border\">\n      <!-- Header Area (Now scrollable) -->\n      <div\n        class=\"tab-header flex flex-col gap-2 border-b border-outline pb-2 px-1 pt-1 flex-shrink-0 bg-transparent transition-all\"\n      >\n        <!-- SYS_MODULE Label -->\n        <div\n          class=\"font-mono text-primary-text mb-0.5 uppercase opacity-80 flex items-center gap-1.5 text-xs tracking-wider\"\n        >\n          <span class=\"w-1.5 h-1.5 bg-primary\"></span>\n          SYS_MODULE // WBOOK_MGR\n        </div>\n\n        <!-- Title & Description -->\n        <div class=\"flex flex-col min-w-0 w-full\">\n          <h1\n            class=\"font-display text-xl md:text-2xl font-bold text-on-surface break-words whitespace-normal leading-tight uppercase\"\n          >\n            世界书管理面板\n          </h1>\n          <p\n            class=\"tab-desc font-body text-on-surface-variant text-xs break-words whitespace-normal mt-1 leading-snug transition-all\"\n          >\n            管理当前角色、全局挂载的世界书数据源，提供检索、状态切换及批量配置功能。\n          </p>\n        </div>\n\n        <!-- Global Actions -->\n        <div class=\"flex flex-wrap justify-between items-center gap-2 mt-1 w-full\">\n          <div class=\"flex flex-wrap items-center gap-2\">\n            <button\n              class=\"px-2 py-1 bg-surface-container-highest border border-outline-variant hover:border-primary text-xs font-bold text-primary-text flex items-center gap-1 transition-colors outline-none cursor-pointer font-display\"\n              @click=\"actions.createNewWorldbook\"\n            >\n              <span class=\"material-symbols-outlined text-sm\">create_new_folder</span>\n              新建书本\n            </button>\n            <button\n              class=\"px-2 py-1 border text-xs font-bold flex items-center gap-1 transition-colors outline-none cursor-pointer font-display\"\n              :class=\"\n                isGlobalBatchMode\n                  ? 'bg-primary-container border-primary-container text-on-primary'\n                  : 'bg-surface-container-highest border-outline-variant text-secondary hover:border-secondary'\n              \"\n              @click=\"toggleGlobalBatchMode\"\n            >\n              <span class=\"material-symbols-outlined text-sm\">library_add_check</span>\n              全局批量\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Global Worldbook Search -->\n      <div\n        class=\"flex items-center bg-surface border border-outline-variant px-2 py-1.5 focus-within:border-primary transition-colors mt-1 w-full min-w-0 box-border\"\n      >\n        <span class=\"material-symbols-outlined text-on-surface-variant text-[calc(14em/14)] flex-shrink-0 mr-2\"\n          >search</span\n        >\n        <input\n          class=\"bg-transparent border-none text-on-surface font-mono focus:outline-none p-0 w-full placeholder-on-surface-variant/50 text-xs min-w-0\"\n          placeholder=\"搜索世界书...\"\n          type=\"text\"\n          v-model=\"filterText\"\n        />\n      </div>\n\n      <!-- Global Batch Toolbar -->\n      <div\n        v-if=\"isGlobalBatchMode\"\n        class=\"flex flex-wrap items-center gap-2 mt-1 pt-2 border-t border-outline-variant/50 w-full\"\n      >\n        <label\n          class=\"flex items-center gap-1 cursor-pointer font-display text-[calc(10em/14)] text-on-surface hover:text-primary-text transition-colors mr-2 flex-shrink-0\"\n        >\n          <input\n            type=\"checkbox\"\n            class=\"accent-primary\"\n            :checked=\"isAllWorldbooksSelected\"\n            @change=\"toggleSelectAllWorldbooks\"\n          />\n          全选\n        </label>\n\n        <div class=\"flex flex-wrap items-center gap-1.5 flex-1 min-w-0\">\n          <button\n            class=\"px-1.5 py-0.5 border border-outline-variant bg-surface hover:bg-surface-variant text-on-surface text-[calc(10em/14)] flex items-center gap-0.5 transition-colors cursor-pointer outline-none\"\n            @click=\"actions.batchPinWorldbooks(selectedWorldbooks, true)\"\n          >\n            <span class=\"material-symbols-outlined text-[calc(12em/14)] text-primary-text\">push_pin</span> 置顶\n          </button>\n          <button\n            class=\"px-1.5 py-0.5 border border-outline-variant bg-surface hover:bg-surface-variant text-on-surface text-[calc(10em/14)] flex items-center gap-0.5 transition-colors cursor-pointer outline-none\"\n            @click=\"actions.batchPinWorldbooks(selectedWorldbooks, false)\"\n          >\n            <span class=\"material-symbols-outlined text-[calc(12em/14)] text-on-surface-variant\">push_pin</span> 消顶\n          </button>\n          <button\n            class=\"px-1.5 py-0.5 border border-outline-variant bg-surface hover:bg-surface-variant text-on-surface text-[calc(10em/14)] flex items-center gap-0.5 transition-colors cursor-pointer outline-none\"\n            @click=\"actions.batchMountWorldbooks(selectedWorldbooks, true)\"\n          >\n            <span class=\"material-symbols-outlined text-[calc(12em/14)]\">link</span> 挂载\n          </button>\n          <button\n            class=\"px-1.5 py-0.5 border border-outline-variant bg-surface hover:bg-surface-variant text-on-surface text-[calc(10em/14)] flex items-center gap-0.5 transition-colors cursor-pointer outline-none\"\n            @click=\"actions.batchMountWorldbooks(selectedWorldbooks, false)\"\n          >\n            <span class=\"material-symbols-outlined text-[calc(12em/14)]\">link_off</span> 卸载\n          </button>\n          <button\n            class=\"px-1.5 py-0.5 border border-error/50 bg-error-container/10 hover:bg-error-container/30 text-error text-[calc(10em/14)] flex items-center gap-0.5 transition-colors cursor-pointer outline-none\"\n            @click=\"handleBatchDelete\"\n          >\n            <span class=\"material-symbols-outlined text-[calc(12em/14)]\">delete</span> 删除\n          </button>\n        </div>\n      </div>\n    </div>\n\n    <!-- Accordion Lists Container -->\n    <div class=\"flex flex-col px-2 pb-2 w-full box-border gap-2\">\n      <WorldbookItem\n        v-for=\"wb in paginatedWorldbooks\"\n        :key=\"wb.name\"\n        :wb=\"wb\"\n        :isGlobalBatchMode=\"isGlobalBatchMode\"\n        v-model:selectedWorldbooks=\"selectedWorldbooks\"\n      />\n\n      <div v-if=\"filteredWorldbooks.length === 0\" class=\"text-on-surface-variant text-xs text-center py-4\">\n        没有找到匹配的世界书。\n      </div>\n\n      <!-- Pagination Controls & Page Size Selector -->\n      <div v-if=\"filteredWorldbooks.length > 0\" class=\"flex flex-wrap justify-between items-center mt-2 mb-2 gap-2\">\n        <div class=\"flex-1\"></div>\n\n        <div v-if=\"totalPages > 1\" class=\"flex items-center gap-4 flex-shrink-0\">\n          <button\n            class=\"w-8 h-8 flex items-center justify-center border border-outline-variant bg-surface hover:bg-surface-variant text-on-surface transition-colors cursor-pointer outline-none disabled:opacity-50 disabled:cursor-not-allowed\"\n            :disabled=\"currentPage <= 1\"\n            @click=\"prevPage\"\n          >\n            <span class=\"material-symbols-outlined text-[calc(18em/14)]\">chevron_left</span>\n          </button>\n\n          <span class=\"font-mono text-[calc(12em/14)] text-on-surface-variant font-bold\">\n            {{ currentPage }} / {{ totalPages }}\n          </span>\n\n          <button\n            class=\"w-8 h-8 flex items-center justify-center border border-outline-variant bg-surface hover:bg-surface-variant text-on-surface transition-colors cursor-pointer outline-none disabled:opacity-50 disabled:cursor-not-allowed\"\n            :disabled=\"currentPage >= totalPages\"\n            @click=\"nextPage\"\n          >\n            <span class=\"material-symbols-outlined text-[calc(18em/14)]\">chevron_right</span>\n          </button>\n        </div>\n        <div v-else class=\"flex-shrink-0\"></div>\n\n        <div class=\"flex-1 flex justify-end\">\n          <div\n            class=\"relative flex items-center border border-outline-variant bg-surface hover:border-primary transition-colors h-8 group\"\n          >\n            <select\n              v-model=\"pageSize\"\n              class=\"appearance-none bg-transparent border-none outline-none text-[calc(11em/14)] font-mono text-on-surface pl-2 pr-6 h-full cursor-pointer z-10 w-full\"\n            >\n              <option :value=\"5\">5 / 页</option>\n              <option :value=\"10\">10 / 页</option>\n              <option :value=\"15\">15 / 页</option>\n              <option :value=\"20\">20 / 页</option>\n              <option :value=\"30\">30 / 页</option>\n              <option :value=\"50\">50 / 页</option>\n            </select>\n            <span\n              class=\"material-symbols-outlined text-[calc(14em/14)] text-on-surface-variant absolute right-1 pointer-events-none group-hover:text-primary transition-colors\"\n              >arrow_drop_down</span\n            >\n          </div>\n        </div>\n      </div>\n\n      <!-- Bottom Spacer to avoid SubNav overlap -->\n      <div class=\"h-14 flex-shrink-0 w-full pointer-events-none\"></div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref, watch } from 'vue';\nimport { configStore, useArkConfig } from '../../../store/config_store';\nimport { useWorldbookActions } from './useWorldbookActions';\nimport WorldbookItem from './WorldbookItem.vue';\n\n// Pinia化前端数据中心改造\nimport { storeToRefs } from 'pinia';\nimport { UIWorldbookEntry, useUIStateStore } from '../../../store/ui_state_store';\n\n// 1. 实例化 Store\nconst uiStore = useUIStateStore();\n// 2. 解构状态变量\nconst { allAvailableWorldbooks, charBoundWorldbooks, globalMountedWorldbooks, worldbookEntriesCache } =\n  storeToRefs(uiStore);\nconst { CONFIG_ENTRY_PREFIX } = uiStore;\n\nconst currentConfig = useArkConfig();\nconst actions = useWorldbookActions();\n\n// --- Local UI State for Worldbook Tab ---\nconst filterText = ref('');\nconst isGlobalBatchMode = ref(false);\nconst selectedWorldbooks = ref<string[]>([]);\n\nconst toggleGlobalBatchMode = () => {\n  isGlobalBatchMode.value = !isGlobalBatchMode.value;\n  if (!isGlobalBatchMode.value) selectedWorldbooks.value = [];\n};\n\n/**\n * 构建带有分类和排序状态的世界书列表对象\n */\nconst filteredWorldbooks = computed(() => {\n  let result = allAvailableWorldbooks.value.map(name => {\n    let type = 'unmounted';\n    if (charBoundWorldbooks.value.includes(name)) type = 'char';\n    else if (globalMountedWorldbooks.value.includes(name)) type = 'global';\n\n    return {\n      name,\n      type,\n      isPinned: currentConfig.value?.pinnedWorldbooks?.includes(name) || false,\n    };\n  });\n\n  if (filterText.value) {\n    const q = filterText.value.toLowerCase();\n    result = result.filter(wb => wb.name.toLowerCase().includes(q));\n  }\n\n  result.sort((a, b) => {\n    const getScore = (wb: { type: string; isPinned: boolean }) => {\n      if (wb.type === 'char') return 5;\n      if (wb.type === 'global' && wb.isPinned) return 4;\n      if (wb.type === 'global') return 3;\n      if (wb.type === 'unmounted' && wb.isPinned) return 2;\n      return 1;\n    };\n    return getScore(b) - getScore(a);\n  });\n\n  return result;\n});\n\n// --- Pagination Logic ---\nconst currentPage = ref(1);\nconst pageSize = ref(currentConfig.value?.worldbookPageSize || 15);\n\nwatch(filterText, () => {\n  currentPage.value = 1;\n});\nwatch(isGlobalBatchMode, () => {\n  currentPage.value = 1;\n});\nwatch(pageSize, newSize => {\n  currentPage.value = 1;\n  configStore.updateConfig({ worldbookPageSize: newSize });\n});\n\nconst totalPages = computed(() => Math.ceil(filteredWorldbooks.value.length / pageSize.value) || 1);\n\nconst paginatedWorldbooks = computed(() => {\n  const start = (currentPage.value - 1) * pageSize.value;\n  const end = start + pageSize.value;\n  return filteredWorldbooks.value.slice(start, end);\n});\n\nconst prevPage = () => {\n  if (currentPage.value > 1) currentPage.value--;\n};\nconst nextPage = () => {\n  if (currentPage.value < totalPages.value) currentPage.value++;\n};\n\n// --- Pre-load Logic ---\nwatch(\n  paginatedWorldbooks,\n  async newWbs => {\n    // 静默预加载当前页的 Worldbook 条目数量\n    for (const wb of newWbs) {\n      if (!worldbookEntriesCache.value[wb.name]) {\n        try {\n          const entries = (await getWorldbook(wb.name)) as unknown as UIWorldbookEntry[];\n          worldbookEntriesCache.value[wb.name] = entries.filter(\n            (e: UIWorldbookEntry) => !(e.name && e.name.startsWith(CONFIG_ENTRY_PREFIX)),\n          );\n        } catch (e) {\n          console.warn(`[ARK_UI] 预加载世界书 ${wb.name} 失败`, e);\n        }\n      }\n    }\n  },\n  { immediate: true },\n);\n\n// --- Selection Logic ---\nconst isAllWorldbooksSelected = computed(() => {\n  const wbs = filteredWorldbooks.value;\n  return wbs.length > 0 && selectedWorldbooks.value.length === wbs.length;\n});\n\nconst toggleSelectAllWorldbooks = (e: Event) => {\n  const checked = (e.target as HTMLInputElement).checked;\n  if (checked) {\n    selectedWorldbooks.value = filteredWorldbooks.value.map(w => w.name);\n  } else {\n    selectedWorldbooks.value = [];\n  }\n};\n\nconst handleBatchDelete = async () => {\n  const deleted = await actions.batchDeleteWorldbooks(selectedWorldbooks.value);\n  if (deleted) selectedWorldbooks.value = [];\n};\n</script>\n\n<style scoped>\n/* 响应式高度压缩：当外部注入了 is-compact-height class 时，触发内部元素的视觉收缩 */\n:global(.is-compact-height) .tab-desc {\n  display: none;\n}\n:global(.is-compact-height) .tab-header {\n  padding-bottom: 2px;\n}\n</style>\n"],"sourceRoot":""}]);
